import{_ as n,c as a,o as i,a3 as t}from"./chunks/framework.CoV49S2T.js";const u=JSON.parse('{"title":"Datenschutz-Optionen","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/privacy-choices.md","filePath":"de/guide/privacy-choices.md","lastUpdated":1787284674000}'),r={name:"de/guide/privacy-choices.md"};function o(s,e,l,d,h,c){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="datenschutz-optionen" tabindex="-1">Datenschutz-Optionen <a class="header-anchor" href="#datenschutz-optionen" aria-label="Permalink to &quot;Datenschutz-Optionen&quot;">​</a></h1><p>ClipboxAI ist eine Local-First-Anwendung. Da Ihre Daten auf Ihrem Gerät bleiben, erfassen, verkaufen oder teilen wir keine personenbezogenen Informationen.</p><h2 id="lokal-gespeicherte-daten" tabindex="-1">Lokal gespeicherte Daten <a class="header-anchor" href="#lokal-gespeicherte-daten" aria-label="Permalink to &quot;Lokal gespeicherte Daten&quot;">​</a></h2><p>ClipboxAI speichert alle Daten lokal auf Ihrem Mac:</p><ul><li>Zwischenablagen-Verlauf und App-Einstellungen</li><li>Benutzerdefinierte Aktionen und Konfiguration</li><li>API-Schlüssel (im Keychain, nur wenn Sie einen Cloud-Anbieter konfigurieren)</li><li>Debug-Protokolle (falls aktiviert)</li></ul><p>Keine dieser Daten wird von der App selbst auf einen Server hochgeladen.</p><h2 id="cloud-ki-opt-in" tabindex="-1">Cloud-KI-Opt-in <a class="header-anchor" href="#cloud-ki-opt-in" aria-label="Permalink to &quot;Cloud-KI-Opt-in&quot;">​</a></h2><p>Cloud-KI-Funktionen sind <strong>standardmäßig deaktiviert</strong>. Sie senden Inhalte nur an den von Ihnen gewählten Anbieter, unter Verwendung Ihres eigenen API-Schlüssels und nur, wenn Sie eine Cloud-Aktion auslösen. Sie können konfigurierte Anbieter unter <strong>Einstellungen → KI</strong> einsehen oder löschen.</p><h2 id="ihre-rechte" tabindex="-1">Ihre Rechte <a class="header-anchor" href="#ihre-rechte" aria-label="Permalink to &quot;Ihre Rechte&quot;">​</a></h2><p>Da ClipboxAI keine personenbezogenen Daten auf unseren Servern erfasst oder speichert, gibt es keine personenbezogenen Daten, auf die wir zugreifen, die wir löschen oder übertragen könnten. Alle Ihre Daten können direkt in der App verwaltet oder durch Entfernen des Container-Ordners der App gelöscht werden:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span></code></pre></div><h2 id="do-not-sell" tabindex="-1">Do Not Sell <a class="header-anchor" href="#do-not-sell" aria-label="Permalink to &quot;Do Not Sell&quot;">​</a></h2><p>ClipboxAI verkauft keine personenbezogenen Informationen. Wir verwenden keine Analysesoftware, Werbung oder Tracking-Dienste irgendeiner Art von Drittanbietern.</p><h2 id="kontakt" tabindex="-1">Kontakt <a class="header-anchor" href="#kontakt" aria-label="Permalink to &quot;Kontakt&quot;">​</a></h2><p>Falls Sie Fragen zu Datenschutz-Optionen haben, öffnen Sie ein Issue unter: <code>https://github.com/clipboxAI/clipboard-site/issues</code></p>',15)])])}const k=n(r,[["render",o]]);export{u as __pageData,k as default};
